import data from "../data/track-lines.json";
import type { TrackLine } from "../types/f1";

// Racing line + pit lane per circuit for the replay map, generated by
// scripts/build-track-lines.mjs from one reference lap and one pit stop in
// OpenF1 data. Keyed by OpenF1 circuit_key.
// JSON arrays infer as number[], not tuples, hence the widening cast.
const lines = data.circuits as unknown as Record<string, TrackLine>;

export function trackLine(circuitKey: number | null | undefined): TrackLine | null {
  return circuitKey != null ? (lines[String(circuitKey)] ?? null) : null;
}
